/**
 * How Standing hollyhock (`tachi-aoi`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/tachi-aoi";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Three hollyhock leaves on stems that rise from one foot: one leaf upright at the top and one a quarter turn to each side, their tips on the layout circle and their notches towards the centre. The leaf is the three-leaf hollyhock's, with its white veins and its curls. A stem 6 wide comes in between a leaf's two lobes and runs on as the black spindle. The top leaf's stem goes straight down to the base. The left branch leaves its leaf between two arcs and joins the upright stem; the right branch passes behind it, so a white line 3 wide parts the two all the way down. Below the branches the trunk flares into a foot that stands on a level line, each side an arc of a circle 100 wide. The top leaf is built first, then the right leaf and the left leaf where they stand, clockwise, and the stems last.","ja":"葵の葉を三枚、一つの根元から立ち上がる茎につけます。一枚は上にまっすぐ立て、残りの二枚は左右に90度ずつ回して置きます。葉先は三枚とも外の円の上にあり、切れ込みは中心を向きます。葉は三つ葉葵と同じで、白い葉脈と渦があります。幅6の茎が二つの耳の間から入り、そのまま黒い紡錘形につながります。上の葉の茎は、根元までまっすぐ下ります。左の枝は、二つの弧にはさまれて葉から出て、まっすぐな茎に合わさります。右の枝は、まっすぐな茎の後ろを通るので、二つの間に幅3の白い線が根元まで残ります。枝の下で幹は左右に広がり、水平な線の上に立つ根元になります。広がりの両側は、幅100の円の弧です。上の葉を作図し、右の葉、左の葉の順に、時計回りにその場で作図して、最後に茎を作図します。"};

export default construction;
export { construction, description };
